نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
غیبت «واحد تولید» این ماه از 0.3٪ به 1.2٪ رسیده در حالی که بقیهٔ واحدها ثابت‌اند. چرا؟ (مدیر منابع انسانی — شرکت لجستیک و حمل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "absence_records",
      "description": "روزهای غیبت به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "days",
        "planned_days"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "absence_rate",
      "description": "نرخ غیبت",
      "formula": "روزهای غیبت / روزهای کاری برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "absence_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month",
    "dimension": "unit"
  }
}

TOOL_OBSERVATION:
{
  "absence_rate_pct": {
    "prev_month": 0.3,
    "curr_month": 1.2,
    "unit": "واحد تولید",
    "other_units": "بدون تغییر محسوس"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "absence_records",
    "filters": {
      "unit": "واحد تولید",
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "event": {
    "note": "از ابتدای ماه، شیفت شب برای پروژهٔ جدید بدون جذب نیروی اضافه شروع شده و همان شیفت بیشترین غیبت را دارد"
  }
}

نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
نرخ ترک «واحد فنی و مهندسی» این سه‌ماهه از 8.5٪ به 16.8٪ رسیده و پروژه‌ها در خطرند. ریشهٔ واقعی کجاست؟ (مدیر منابع انسانی — شرکت لجستیک و حمل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    },
    {
      "dataset": "payroll",
      "description": "دستمزد و مزایا به تفکیک واحد",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "cost_m_toman"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است",
    "سیاست پرداخت سالانه بازبینی می‌شود؛ بازار نیروی فنی رقابتی است"
