  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "turnover_rate"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "turnover_pct": {
    "prev_quarter": 8.5,
    "curr_quarter": 16.8,
    "unit": "واحد فنی و مهندسی"
  }
}

