{
  "tool": "get_dataset",
  "arguments": {
    "name": "exits",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "exits_by_tenure": {
    "بالای ۵ سال سابقه (مهندسان ارشد)": 72,
    "کمتر از ۲ سال": 38
  },
  "dominant_reason": "پیشنهاد حقوق بالاتر از رقبا"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "payroll",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "market_gap_note": "بررسی حقوق بازار نشان می‌دهد حقوق مهندسان ارشد این واحد 22٪ زیر میانگین بازار است و دو رقیب در سه ماه اخیر جذب فعال داشته‌اند"
