نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
11 مهندس ارشد واحد فنی در خطر خروج‌اند (شکاف حقوقی 19٪ با بازار). بین افزایش حقوق و جایگزینی کدام به‌صرفه‌تر است؟ (مدیر منابع انسانی — شرکت مهندسی و ساخت)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "hires",
      "description": "استخدام‌ها: تعداد، هزینه و منبع جذب",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "count",
        "cost_m_toman"
      ]
    },
    {
      "dataset": "payroll",
      "description": "دستمزد و مزایا به تفکیک واحد",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "cost_m_toman"
      ]
    },
    {
      "dataset": "vacancy_log",
      "description": "سوابق جای خالی: تاریخ باز و پر شدن",
      "dimensions": [
        "unit",
        "position"
      ],
      "measures": [
        "days_to_fill"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_hire",
      "description": "هزینهٔ هر استخدام",
      "formula": "مجموع هزینهٔ جذب و آموزش / تعداد استخدام",
      "unit": "میلیون تومان",
      "dimensions": [
        "unit",
        "period"
      ]
    },
    {
      "metric": "time_to_fill",
      "description": "زمان پر کردن جای خالی",
      "formula": "میانگین روز از تأیید سمت تا حضور نیرو",
      "unit": "روز",
      "dimensions": [
        "unit",
        "position"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cost_per_hire"
    ],
    "period": "last_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "cost_per_hire_m_toman": 80,
  "note": "فقط جذب؛ بدون افت بهره‌وری شش‌ماههٔ نیروی جدید"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "time_to_fill"
    ],
    "period": "curr_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "time_to_fill_days": 85,
  "position": "مهندس ارشد"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "payroll",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "raise_cost_annual_m_toman": 470,
  "replacement_full_cost_annual_m_toman": 810,
  "market_gap_pct": 19
}

