به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک منابع انسانی ما چیست و بودجهٔ نگهداشت را کجا خرج کنیم. (مدیر منابع انسانی در گفتگو با مدیرعامل — شرکت لجستیک و حمل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    },
    {
      "dataset": "vacancy_log",
      "description": "سوابق جای خالی: تاریخ باز و پر شدن",
      "dimensions": [
        "unit",
        "position"
      ],
      "measures": [
        "days_to_fill"
      ]
    },
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "time_to_fill",
      "description": "زمان پر کردن جای خالی",
      "formula": "میانگین روز از تأیید سمت تا حضور نیرو",
      "unit": "روز",
      "dimensions": [
        "unit",
        "position"
      ]
    },
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است",
    "سیاست پرداخت سالانه بازبینی می‌شود؛ بازار نیروی فنی رقابتی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "headcount",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "key_persons": 9,
  "note": "دانش فرایندهای حیاتی (تولید و کیفیت) به 9 نفر وابسته است"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "time_to_fill"
    ],
    "period": "curr_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "time_to_fill_days": 120,
  "position": "مهندس/تکنسین ارشد"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "turnover_rate"
    ],
    "period": "curr_quarter",
    "comparison": "prev_quarter"
  }
}

TOOL_OBSERVATION:
{
  "turnover_pct": 16.2,
  "unit": "واحدهای فنی و تولید"
}

