نرخ ترک‌خدمت سه ماه است بالا می‌رود و مدیر مالی می‌گوید تا پایان سال به ۳۰٪ می‌رسد و باید همین حالا استخدام سراسری شروع شود. این پیش‌بینی چقدر معتبر است؟ (مدیر منابع انسانی — هلدینگ خدماتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است",
    "سیاست پرداخت سالانه بازبینی می‌شود؛ بازار نیروی فنی رقابتی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "turnover_rate",
    "granularity": "month",
    "range": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "turnover_monthly_pct": [
    {
      "month": "m0",
      "value": 8.7
    },
    {
      "month": "m1",
      "value": 9.7
    },
    {
      "month": "m2",
      "value": 10.7
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "exits",
    "filters": {
      "period": "last_3_months"
    }
  }
}

