    "prev_month": 0.2,
    "curr_month": 1.4,
    "unit": "واحد تولید",
    "other_units": "بدون تغییر محسوس"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "absence_records",
    "filters": {
      "unit": "واحد تولید",
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
