به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک منابع انسانی ما چیست و بودجهٔ نگهداشت را کجا خرج کنیم. (مدیر منابع انسانی در گفتگو با مدیرعامل — زنجیرهٔ خرده‌فروشی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    },
    {
      "dataset": "vacancy_log",
      "description": "سوابق جای خالی: تاریخ باز و پر شدن",
      "dimensions": [
        "unit",
        "position"
      ],
      "measures": [
        "days_to_fill"
      ]
    },
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "time_to_fill",
      "description": "زمان پر کردن جای خالی",
      "formula": "میانگین روز از تأیید سمت تا حضور نیرو",
      "unit": "روز",
      "dimensions": [
        "unit",
        "position"
      ]
    },
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است",
    "سیاست پرداخت سالانه بازبینی می‌شود؛ بازار نیروی فنی رقابتی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "headcount",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "key_persons": 10,
  "note": "دانش فرایندهای حیاتی (تولید و کیفیت) به 10 نفر وابسته است"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "time_to_fill"
    ],
    "period": "curr_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "time_to_fill_days": 120,
  "position": "مهندس/تکنسین ارشد"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "turnover_rate"
    ],
    "period": "curr_quarter",
    "comparison": "prev_quarter"
  }
}

TOOL_OBSERVATION:
{
  "turnover_pct": 13.2,
  "unit": "واحدهای فنی و تولید"
}

نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
غیبت «واحد فنی و مهندسی» این ماه از 0.3٪ به 1.2٪ رسیده در حالی که بقیهٔ واحدها ثابت‌اند. چرا؟ (مدیر منابع انسانی — شرکت لجستیک و حمل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "absence_records",
      "description": "روزهای غیبت به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "days",
        "planned_days"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "absence_rate",
      "description": "نرخ غیبت",
      "formula": "روزهای غیبت / روزهای کاری برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "absence_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month",
    "dimension": "unit"
  }
}

TOOL_OBSERVATION:
{
  "absence_rate_pct": {
    "prev_month": 0.3,
    "curr_month": 1.2,
    "unit": "واحد فنی و مهندسی",
    "other_units": "بدون تغییر محسوس"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "absence_records",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "event": {
    "note": "از ابتدای ماه، شیفت شب برای پروژهٔ جدید بدون جذب نیروی اضافه شروع شده و همان شیفت بیشترین غیبت را دارد"
  }
}

